"""stocklib: a tiny stock-keeping library (the WIP-curve experiment's target, open-fleet #604)."""
"""A stock ledger: quantities per SKU."""


class Ledger:
    def __init__(self):
        self._stock = {}

    def add(self, sku, qty):
        if qty <= 0:
            raise ValueError("qty to add must be positive")
        self._stock[sku] = self._stock.get(sku, 0) + qty

    def remove(self, sku, qty):
        if qty <= 0:
            raise ValueError("qty to remove must be positive")
        self._stock[sku] = self._stock.get(sku, 0) - qty

    def quantity(self, sku):
        return self._stock.get(sku, 0)

    def skus(self):
        return sorted(self._stock)
"""Plain-text reports over a Ledger."""


def totals(ledger):
    return int(sum(ledger.quantity(sku) for sku in ledger.skus()))


def summary(ledger):
    lines = [f"{sku}: {ledger.quantity(sku)}" for sku in ledger.skus()]
    lines.append(f"TOTAL {totals(ledger)}")
    return "\n".join(lines)
"""Text helpers."""
import re


def slugify(text):
    text = text.strip().lower()
    text = re.sub(r"[^a-z0-9]+", "-", text)
    return text.strip("-")
"""Unit conversion for stock quantities, by mass."""

FACTORS = {
    "g": 1,
    "kg": 1000,
}


def convert(value, from_unit, to_unit):
    """`value` in `from_unit`, expressed in `to_unit`."""
    try:
        return value * FACTORS[from_unit] / FACTORS[to_unit]
    except KeyError as err:
        raise ValueError(f"unknown unit {err.args[0]!r}") from None

